// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, LogFile} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    LogFile log;

    function setUp() public {
        c = new C();
        log = new LogFile();
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(log));
        vm.assume(actor != address(c));
        vm.assume(uint160(actor) > 100);
        amount = bound(amount, 1, 1 ether);

        // Initialize log file to the supplied LogFile contract
        vm.prank(actor);
        c.SetLogFile(address(log));

        // Rule: after SetLogFile(log), any deposit must succeed (it logs to a real LogFile)
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(0) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && log.History(0) == (actor, block.timestamp));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    LogFile log;

    function setUp() public {
        c = new C();
        log = new LogFile();
    }

    function testFuzz_property(address actor, uint256 amount, uint256 lockTime) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(log) && actor != address(this));
        amount = bound(amount, 1, 1 ether);
        lockTime = bound(lockTime, 0, 365 days);

        c.SetLogFile(address(log));

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(lockTime);

        bool ok = true;
        address sender;
        try log.History(0) returns (address s, string memory, uint256, uint256) {
            sender = s;
        } catch {
            ok = false;
        }
        assertTrue(ok && sender == actor);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint256 Val;
        uint256 Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint256 _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

