pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    RevertingLog lg;

    function setUp() public {
        c = new C();
        lg = new RevertingLog();
        c.SetLogFile(address(lg));
    }

    function testFuzz_property(address actor, uint256 amount, uint256 lockTime) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(lg));
        vm.assume(actor.code.length == 0);
        amount = bound(amount, 0, 1 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        bool reverted = false;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: after SetLogFile(revertingLog), any Put must revert,
        // because the stored log is the reverting log contract.
        assertTrue(reverted);
    }
}

contract RevertingLog {
    function AddMessage(address, string calldata, uint256) external pure {
        revert();
    }
}

