    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor, uint32 lockTime) public {
        vm.assume(actor != address(0));
        vm.assume(address(c) != actor);
        amount = bound(amount, 1, 1 ether);
        c.SetLogFile(address(this));
        c.Initialized();
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(lockTime) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "Put should succeed with a valid log address set");
    }
}

